import java.sql.Connection;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;

public class StudyTopicDAO {

    // Save a topic and return the ID generated by MySQL
    public int addTopic(StudyTopic topic) {
        String sql = "INSERT INTO study_topics " +
                "(topic_name, subject, planned_date, estimated_minutes, completed) " +
                "VALUES (?, ?, ?, ?, ?)";

        try (Connection connection = DatabaseConnection.getConnection();
             PreparedStatement statement = connection.prepareStatement(
                     sql, java.sql.Statement.RETURN_GENERATED_KEYS)) {

            statement.setString(1, topic.getTopicName());
            statement.setString(2, topic.getSubject());
            statement.setDate(3, Date.valueOf(topic.getPlannedDate()));
            statement.setInt(4, topic.getEstimatedMinutes());
            statement.setBoolean(5, topic.isCompleted());

            statement.executeUpdate();

            try (ResultSet keys = statement.getGeneratedKeys()) {
                if (keys.next()) {
                    int generatedId = keys.getInt(1);
                    System.out.println(
                            "Topic saved successfully! ID: " + generatedId);
                    return generatedId;
                }
            }

        } catch (SQLException e) {
            System.out.println("Could not save topic to MySQL.");
            e.printStackTrace();
        }

        return -1;
    }

    // Load all topics from MySQL
    public List<StudyTopic> getAllTopics() {
        List<StudyTopic> topics = new ArrayList<>();

        String sql = "SELECT id, topic_name, subject, planned_date, " +
                "estimated_minutes, completed " +
                "FROM study_topics ORDER BY id";

        try (Connection connection = DatabaseConnection.getConnection();
             PreparedStatement statement = connection.prepareStatement(sql);
             ResultSet resultSet = statement.executeQuery()) {

            while (resultSet.next()) {
                StudyTopic topic = new StudyTopic(
                        resultSet.getInt("id"),
                        resultSet.getString("topic_name"),
                        resultSet.getString("subject"),
                        resultSet.getDate("planned_date").toLocalDate(),
                        resultSet.getInt("estimated_minutes"),
                        resultSet.getBoolean("completed")
                );

                topics.add(topic);
            }

        } catch (SQLException e) {
            System.out.println("Could not load topics from MySQL.");
            e.printStackTrace();
        }

        return topics;
    }

    // Update a topic's completion status in MySQL
    public boolean markTopicCompleted(int id) {
        String sql = "UPDATE study_topics SET completed = TRUE WHERE id = ?";

        try (Connection connection = DatabaseConnection.getConnection();
             PreparedStatement statement = connection.prepareStatement(sql)) {

            statement.setInt(1, id);

            int rowsUpdated = statement.executeUpdate();
            return rowsUpdated > 0;

        } catch (SQLException e) {
            System.out.println("Could not update topic in MySQL.");
            e.printStackTrace();
            return false;
        }
    }

    // Delete a study topic from MySQL using its ID
    public boolean deleteTopic(int id) {
        String sql = "DELETE FROM study_topics WHERE id = ?";

        try (Connection connection = DatabaseConnection.getConnection();
             PreparedStatement statement = connection.prepareStatement(sql)) {

            statement.setInt(1, id);

            int rowsDeleted = statement.executeUpdate();
            return rowsDeleted > 0;

        } catch (SQLException e) {
            System.out.println("Could not delete topic from MySQL.");
            e.printStackTrace();
            return false;
        }
    }

}